fn solve(r: i8, g: i8, b: i8) -> i8 {
    // Promote to a wider type to avoid overflow when summing up to 3 * 127 = 381
    let r = r as i32;
    let g = g as i32;
    let b = b as i32;

    // Maximum tables if we only care about total items
    let by_total = (r + g + b) / 3;
    // Maximum tables if we avoid using only one color at a time:
    let by_rg = r + g;
    let by_rb = r + b;
    let by_gb = g + b;

    // The answer is the minimum of these four constraints
    let ans = by_total.min(by_rg).min(by_rb).min(by_gb);

    // It is guaranteed to be nonnegative and ≤ 127, so it fits back into i8
    ans as i8
}

